    S.letter l.inv = rotor S.s (-(if l.pos then S.biv (siteL l.idx) (siteR l.idx)
      else -S.biv (siteL l.idx) (siteR l.idx)))

theorem letter_eq (l : Letter n) :
    S.letter l = rotor S.s (if l.pos then S.biv (siteL l.idx) (siteR l.idx)
      else -S.biv (siteL l.idx) (siteR l.idx))

