    (hs : ∀ p ∈ ts, p.1.Sound truth) {a : α} {v : Bool} (h : runTiers ts a = some v) :
    v = truth a

theorem kellyRun_sound {truth : α → Bool} {total floor : ℕ} {ts : List (TierState α)}
    (hs : ∀ s ∈ ts, s.tier.Sound truth) {a : α} {v : Bool}
    (h : kellyRun total floor ts a = some v) : v = truth a

theorem mem_tiers_of_preserves {upd : List (TierState α) → α → List (TierState α)}
    (hupd : PreservesTiers upd) {ts : List (TierState α)} {a : α} {s : TierState α}
    (h : s ∈ upd ts a) : ∃ s' ∈ ts, s.tier = s'.tier

theorem graduatedRun_eq {truth : α → Bool} {total floor : ℕ} {ts : List (TierState α)}
    (hs : ∀ s ∈ ts, s.tier.Sound truth) {dec : α → Bool} (hdec : ∀ a, dec a = truth a)
    (a : α) : graduatedRun total floor ts dec a = truth a

theorem graduatedRun_of_decided {total floor : ℕ} {ts : List (TierState α)} {dec : α → Bool}
    {a : α} {v : Bool} (h : kellyRun total floor ts a = some v) :
    graduatedRun total floor ts dec a = v

