    (hG : G.IsEdgeConnected d) {u w₁ w₂ : V} (hdeg : (G.neighborSet u).encard ≤ d)
    (h₁ : G.Adj u w₁) (h₂ : G.Adj u w₂) : ∃ q : G.Walk w₁ w₂, u ∉ q.support

